sed -i '/const unsubscribeSteps = onSnapshot/i \    const unsubscribeEmailTemplates = onSnapshot(collection(db, '\''emailTemplates'\''), (snapshot) => {\n      if (snapshot.empty) {\n        const defaultTemplates: EmailTemplate[] = [\n          { id: '\''t1'\'', name: '\''Assessment - Not Recommended to Proceed'\'', subject: '\''Visa Assessment Update - {{referenceId}}'\'', body: '\''Hello {{applicantName}},\\n\\nThank you for allowing us to review your visa profile.\\n\\nBased on the information currently available, we are unable to recommend proceeding with the visa application at this stage.\\n\\nThis assessment is based on the information provided and does not represent a decision by the relevant immigration authority.\\n\\nIf your circumstances change or additional supporting documents become available, we can review your profile again.\\n\\nRegards,\\n{{companyName}}\\n\\n{{companyEmail}}\\n{{companyPhone}}'\'' },\n          { id: '\''t2'\'', name: '\''Assessment - You Can Proceed'\'', subject: '\''Visa Assessment - Next Steps'\'', body: '\''Hello {{applicantName}},\\n\\nThank you for choosing {{companyName}}.\\n\\nBased on the information currently available, your profile can proceed to the next stage of the visa application process.\\n\\nPlease note that this assessment does not guarantee visa approval. The final decision is made by the relevant immigration authority.\\n\\nTo continue with the process, the required service payment must be completed.\\n\\nOnce payment is confirmed, we can proceed with the next steps and required documentation.\\n\\nApplication Reference:\\n{{referenceId}}\\n\\nDestination:\\n{{destination}}\\n\\nRegards,\\n{{companyName}}\\n\\n{{companyEmail}}\\n{{companyPhone}}'\'' }\n        ];\n        defaultTemplates.forEach(template => setDoc(doc(db, '\''emailTemplates'\'', template.id), template));\n      }\n      setEmailTemplates(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as EmailTemplate)));\n    });\n    const unsubscribeEmailDrafts = onSnapshot(collection(db, '\''emailDrafts'\''), (snapshot) => {\n      setEmailDrafts(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as EmailDraft)));\n    });\n    const unsubscribeEmailHistory = onSnapshot(collection(db, '\''emailHistory'\''), (snapshot) => {\n      const records = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as EmailRecord));\n      records.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());\n      setEmailHistory(records);\n    });' src/store/AppContext.tsx

